<?php
/**
 * Generate the per-app PWA artwork for the Sale, Delivery and Customer apps,
 * plus the site-wide favicon.
 *
 * Every surface owns a distinct colour + letter so no two browser tabs or
 * home-screen installs ever look the same:
 *
 *   sale       #e53935  "S"  — matches sale app theme-color
 *   delivery   #0f766e  "D"  — matches delivery app --dlv
 *   customer   #e11d48  "C"  — matches customer app theme-color
 *
 * POS and Ecommerce artwork is generated by generate_icons.php /
 * generate_ecom_icons.php and is intentionally left untouched here.
 *
 * Run: php public/pwa/generate_app_icons.php
 */

$outDir = __DIR__;
if (! is_dir($outDir)) {
    mkdir($outDir, 0755, true);
}

if (! function_exists('imagecreatetruecolor')) {
    fwrite(STDERR, "GD extension required\n");
    exit(1);
}

const ICON_SS = 4; // supersampling factor for smooth corners

/** Candidate bold sans faces, most preferred first. */
function iconFontPath(): ?string
{
    static $found = null;
    if ($found !== null) {
        return $found ?: null;
    }

    $candidates = [
        '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',
        '/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf',
        '/usr/share/fonts/truetype/freefont/FreeSansBold.ttf',
        '/usr/share/fonts/truetype/lato/Lato-Heavy.ttf',
        '/Library/Fonts/Arial Bold.ttf',
        'C:/Windows/Fonts/arialbd.ttf',
    ];

    foreach ($candidates as $path) {
        if (is_readable($path)) {
            return $found = $path;
        }
    }

    return $found = '';
}

function hexToRgb(string $hex): array
{
    $hex = ltrim($hex, '#');

    return [
        hexdec(substr($hex, 0, 2)),
        hexdec(substr($hex, 2, 2)),
        hexdec(substr($hex, 4, 2)),
    ];
}

/** Fill a rounded rectangle on a truecolour canvas. */
function fillRoundedRect($im, int $x, int $y, int $w, int $h, int $r, int $color): void
{
    imagefilledrectangle($im, $x + $r, $y, $x + $w - $r - 1, $y + $h - 1, $color);
    imagefilledrectangle($im, $x, $y + $r, $x + $w - 1, $y + $h - $r - 1, $color);

    $d = $r * 2;
    imagefilledellipse($im, $x + $r, $y + $r, $d, $d, $color);
    imagefilledellipse($im, $x + $w - $r - 1, $y + $r, $d, $d, $color);
    imagefilledellipse($im, $x + $r, $y + $h - $r - 1, $d, $d, $color);
    imagefilledellipse($im, $x + $w - $r - 1, $y + $h - $r - 1, $d, $d, $color);
}

/**
 * Tight bounding box of the opaque pixels in a transparent canvas.
 *
 * imagettfbbox() reports the advance width rather than the true ink edges, so
 * centring on it leaves round glyphs visibly off-centre. Measuring the pixels
 * keeps S / D / C optically centred whatever font is installed.
 *
 * @return array{int,int,int,int}|null  [minX, minY, maxX, maxY]
 */
function inkBounds($im): ?array
{
    $w = imagesx($im);
    $h = imagesy($im);
    $minX = $w;
    $minY = $h;
    $maxX = -1;
    $maxY = -1;

    for ($y = 0; $y < $h; $y++) {
        for ($x = 0; $x < $w; $x++) {
            $c = imagecolorat($im, $x, $y);
            $alpha = ($c >> 24) & 0x7F;
            if ($alpha < 110) {
                $minX = min($minX, $x);
                $maxX = max($maxX, $x);
                $minY = min($minY, $y);
                $maxY = max($maxY, $y);
            }
        }
    }

    return $maxX < 0 ? null : [$minX, $minY, $maxX, $maxY];
}

/**
 * Draw $text centred in the given box, with its cap height filling $ratio of it.
 * Uses a real TTF when one is installed so the glyph stays crisp at 512px,
 * falling back to the built-in GD bitmap font when none is found.
 */
function drawCenteredLetter($im, string $text, int $cx, int $cy, int $box, float $ratio, int $color): void
{
    $font = iconFontPath();
    $targetH = (int) round($box * $ratio);

    if ($font !== '') {
        // Oversized scratch canvas so the glyph is never clipped.
        $pad = (int) round($box * 0.5);
        $scratch = imagecreatetruecolor($box + $pad * 2, $box + $pad * 2);
        imagesavealpha($scratch, true);
        imagefill($scratch, 0, 0, imagecolorallocatealpha($scratch, 0, 0, 0, 127));

        // Size by cap height rather than em, so single letters read large and
        // multi-letter marks like "POS" still fit.
        $size = (int) round($targetH / 0.72);
        imagettftext($scratch, $size, 0, $pad, $pad + (int) round($size * 0.75), $color, $font, $text);

        $ink = inkBounds($scratch);

        if ($ink !== null) {
            [$minX, $minY, $maxX, $maxY] = $ink;
            $inkW = $maxX - $minX + 1;
            $inkH = $maxY - $minY + 1;
            $scale = $targetH / $inkH;
            $dstW = (int) round($inkW * $scale);
            $dstH = $targetH;
            imagecopyresampled(
                $im,
                $scratch,
                (int) round($cx - $dstW / 2),
                (int) round($cy - $dstH / 2),
                $minX,
                $minY,
                $dstW,
                $dstH,
                $inkW,
                $inkH
            );
            imagedestroy($scratch);

            return;
        }

        imagedestroy($scratch);
    }

    $bw = imagefontwidth(5) * strlen($text);
    $bh = imagefontheight(5);
    $tmp = imagecreatetruecolor($bw + 4, $bh + 4);
    imagesavealpha($tmp, true);
    imagefill($tmp, 0, 0, imagecolorallocatealpha($tmp, 0, 0, 0, 127));
    imagestring($tmp, 5, 2, 2, $text, $color);
    imagecopyresampled($im, $tmp, (int) round($cx - $targetH / 2), (int) round($cy - $targetH / 2), 0, 0, $targetH, $targetH, $bw + 4, $bh + 4);
    imagedestroy($tmp);
}

/**
 * Build one icon at ICON_SS scale, then downsample to $size.
 *
 * @param  bool  $bleed  true = full-bleed square (apple-touch / maskable),
 *                       false = rounded square (tab + home-screen "any" icon)
 */
function renderIcon(int $size, string $hex, string $letter, bool $bleed): GdImage
{
    $s = $size * ICON_SS;
    $im = imagecreatetruecolor($s, $s);
    imagesavealpha($im, true);
    imagefill($im, 0, 0, imagecolorallocatealpha($im, 0, 0, 0, 127));

    [$r, $g, $b] = hexToRgb($hex);
    $bg = imagecolorallocate($im, $r, $g, $b);

    if ($bleed) {
        imagefilledrectangle($im, 0, 0, $s - 1, $s - 1, $bg);
    } else {
        fillRoundedRect($im, 0, 0, $s, $s, (int) round($s * 0.22), $bg);
    }

    $white = imagecolorallocate($im, 255, 255, 255);
    drawCenteredLetter($im, $letter, (int) round($s / 2), (int) round($s / 2), $s, 0.44, $white);

    $out = imagecreatetruecolor($size, $size);
    imagesavealpha($out, true);
    imagecopyresampled($out, $im, 0, 0, 0, 0, $size, $size, $s, $s);
    imagedestroy($im);

    return $out;
}

/** Pack PNG buffers into a multi-size .ico container (Vista+ format). */
function buildIco(array $pngs): string
{
    ksort($pngs);
    $count = count($pngs);

    $ico = pack('vvv', 0, 1, $count);
    $offset = 6 + $count * 16;
    $images = '';

    foreach ($pngs as $size => $png) {
        $len = strlen($png);
        $ico .= pack(
            'CCCCvvVV',
            $size >= 256 ? 0 : $size,
            $size >= 256 ? 0 : $size,
            0,
            0,
            1,
            32,
            $len,
            $offset
        );
        $images .= $png;
        $offset += $len;
    }

    return $ico.$images;
}

$apps = [
    'sale' => ['prefix' => 'sale-icon', 'hex' => '#e53935', 'letter' => 'S'],
    'delivery' => ['prefix' => 'delivery-icon', 'hex' => '#0f766e', 'letter' => 'D'],
    'customer' => ['prefix' => 'customer-icon', 'hex' => '#e11d48', 'letter' => 'C'],
];

foreach ($apps as $name => $app) {
    $p = $app['prefix'];

    foreach ([192, 512] as $size) {
        $im = renderIcon($size, $app['hex'], $app['letter'], false);
        imagepng($im, $outDir.'/'.$p.'-'.$size.'.png', 6);
        imagedestroy($im);
    }

    // Full-bleed variants for the iOS home screen and Android maskable.
    $apple = renderIcon(180, $app['hex'], $app['letter'], true);
    imagepng($apple, $outDir.'/'.$p.'-apple-touch-icon.png', 6);
    imagedestroy($apple);

    $maskable = renderIcon(512, $app['hex'], $app['letter'], true);
    imagepng($maskable, $outDir.'/'.$p.'-maskable-512.png', 6);
    imagedestroy($maskable);

    echo "  {$name}: {$app['hex']} \"{$app['letter']}\"\n";
}

// Site-wide favicon, derived from the existing POS mark so its artwork is unchanged.
$source = $outDir.'/icon-192.png';
if (is_readable($source)) {
    $src = imagecreatefrompng($source);
    $pngs = [];

    foreach ([16, 32, 48] as $size) {
        $im = imagecreatetruecolor($size, $size);
        imagesavealpha($im, true);
        imagecopyresampled($im, $src, 0, 0, 0, 0, $size, $size, imagesx($src), imagesy($src));
        ob_start();
        imagepng($im);
        $pngs[$size] = ob_get_clean();
        imagedestroy($im);
    }

    imagedestroy($src);
    file_put_contents(dirname($outDir).'/favicon.ico', buildIco($pngs));
    echo "  favicon: 16/32/48 from pwa/icon-192.png\n";
}

echo "Generated icons in {$outDir}\n";